const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, message: row.error || 'Character canon request failed.' } }];
}
const result = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;
const canon = typeof row.canon === 'string' ? JSON.parse(row.canon) : row.canon;
return [{ json: { ok: true, ...(result || {}), ...(canon ? { canon } : {}) } }];
